const item = $json;

function decodeBase64Url(value = "") {
  if (!value) return "";
  const normalized = value.replace(/-/g, "+").replace(/_/g, "/");
  const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, "=");
  const binary = atob(padded);
  const bytes = Array.from(binary, char =>
    `%${char.charCodeAt(0).toString(16).padStart(2, "0")}`
  ).join("");

  return decodeURIComponent(bytes);
}

function htmlToText(html = "") {
  return html
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function collectParts(part, out = { text: [], html: [] }) {
  if (!part) return out;
  const mimeType = part.mimeType || "";
  const data = part.body?.data;
  if (data && mimeType.includes("text/plain")) out.text.push(decodeBase64Url(data));
  if (data && mimeType.includes("text/html")) out.html.push(htmlToText(decodeBase64Url(data)));
  for (const child of part.parts || []) collectParts(child, out);
  return out;
}

function header(name) {
  const wanted = name.toLowerCase();
  const headers = item.payload?.headers || item.headers || [];

  if (Array.isArray(headers)) {
    return headers.find(h => h.name?.toLowerCase() === wanted)?.value || "";
  }

  if (headers && typeof headers === "object") {
    return headers[name] || headers[wanted] || headers[name.toUpperCase()] || "";
  }

  return "";
}

function parseFrom(value = "") {
  if (!value) return { name: "", email: "" };

  if (typeof value === "object") {
    const first = value.value?.[0] || value;
    const email = first.address || first.email || value.address || value.email || "";
    const name = first.name || value.name || "";

    if (email) {
      return {
        name: String(name).trim(),
        email: String(email).trim(),
      };
    }

    value = value.text || value.html || "";
  }

  const raw = String(value).trim();
  const emailMatch = raw.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);

  if (emailMatch) {
    const email = emailMatch[0];
    const name = raw
      .replace(email, "")
      .replace(/^From:\s*/i, "")
      .replace(/[<>"']/g, "")
      .trim();

    return { name, email };
  }

  const text = raw.replace(/^From:\s*/i, "").replace(/<[^>]*>/g, "").trim();
  const match = text.match(/^(?:"?([^"<]*)"?\s)?<?([^<>\s]+@[^<>\s]+)>?$/);

  return {
    name: (match?.[1] || "").trim(),
    email: (match?.[2] || "").trim(),
  };
}

const parts = collectParts(item.payload);
const rawBody = (
  parts.text.join("\n") ||
  item.text ||
  item.textPlain ||
  parts.html.join("\n") ||
  htmlToText(item.html || item.textAsHtml || "") ||
  item.snippet ||
  ""
).trim();
const quotedRegex = /^On .+ wrote:[\s\S]*$/m;
const sigSplit = rawBody.split(/\n-- ?\n/);

const body_clean = sigSplit[0]
  .replace(quotedRegex, "")
  .replace(/^>.*$/gm, "")
  .replace(/\n{3,}/g, "\n\n")
  .trim();

const from = parseFrom(
  header("Reply-To") ||
  header("From") ||
  header("Return-Path") ||
  item.replyTo ||
  item.from ||
  item.sender ||
  ""
);

if (!from.email) {
  throw new Error("Could not extract a valid sender email address from the Gmail message.");
}

return {
  json: {
    from_email: from.email || "",
    from_name: from.name || "",
    subject: header("Subject") || item.subject || "(no subject)",
    date: header("Date") || item.date || item.internalDate,
    thread_id: item.threadId,
    message_id: item.id,
    rfc_message_id: header("Message-ID"),
    body_clean,
  },
};

parameters.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "category",
    "priority",
    "summary",
    "needs_reply",
    "suggested_reply",
    "gmail_label",
    "slack_notify",
    "reasoning"
  ],
  "properties": {
    "category": {
      "type": "string",
      "enum": ["actionable", "informational", "promotional", "automated", "spam"]
    },
    "priority": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5
    },
    "summary": {
      "type": "string",
      "description": "Maximum two sentences."
    },
    "needs_reply": {
      "type": "boolean"
    },
    "suggested_reply": {
      "type": "string",
      "description": "Draft text for useful emails that need a reply, 'No reply recommended.' for useful no-reply emails, and empty string for spam/promotional/no-content emails."
    },
    "gmail_label": {
      "type": "string",
      "enum": ["AI/Needs Reply", "AI/Urgent", "AI/FYI", "AI/Ignore"]
    },
    "slack_notify": {
      "type": "boolean",
      "description": "True only for priority >= 3 or urgent/time-bound messages."
    },
    "reasoning": {
      "type": "string",
      "description": "One sentence explaining the category and priority."
    }
  }
}

